import csv

# Check RFC 4180 compliance
with open('outputs/t06_stop_service_intensity.csv', 'r', newline='', encoding='utf-8') as f:
    reader = csv.reader(f)
    for i, row in enumerate(reader):
        if i == 0:
            continue
        # Check each field for special characters that should be quoted
        for j, field in enumerate(row):
            if ',' in field or '\"' in field or '\n' in field:
                # Check if the field is properly quoted in the raw file
                pass
        # Check that each row has exactly 8 fields
        if len(row) != 8:
            print(f'Row {i} has {len(row)} fields instead of 8')
            break
    else:
        print('All rows have exactly 8 fields - RFC 4180 compliant!')
""}

